CREATE TABLE "c_Author" ("id" BIGINT NOT NULL, "a_Author_display_name" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Comment" ("id" BIGINT NOT NULL, "a_Comment_body" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "c_Post" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_Post_title" TEXT NOT NULL, "a_Post_body" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('Post','SponsoredPost')));
CREATE TABLE "c_SponsoredPost" ("id" BIGINT NOT NULL, "dtype" TEXT NOT NULL, "a_SponsoredPost_campaign_code" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("id", "dtype"), CHECK (dtype IN ('SponsoredPost')));
CREATE TABLE "c_Tag" ("id" BIGINT NOT NULL, "a_Tag_label" TEXT NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "l_AuthorPosts" ("r_AuthorPosts_source_id" BIGINT NOT NULL, "r_AuthorPosts_target_id" BIGINT NOT NULL, "r_AuthorPosts_target_dtype" TEXT NOT NULL, PRIMARY KEY ("r_AuthorPosts_source_id", "r_AuthorPosts_target_id"), UNIQUE ("r_AuthorPosts_target_id"), CHECK ("r_AuthorPosts_target_dtype" IS NULL OR "r_AuthorPosts_target_dtype" IN ('Post','SponsoredPost')));
CREATE TABLE "l_PostComments" ("r_PostComments_source_id" BIGINT NOT NULL, "r_PostComments_source_dtype" TEXT NOT NULL, "r_PostComments_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PostComments_source_id", "r_PostComments_target_id"), UNIQUE ("r_PostComments_target_id"), CHECK ("r_PostComments_source_dtype" IS NULL OR "r_PostComments_source_dtype" IN ('Post','SponsoredPost')));
CREATE TABLE "l_PostTags" ("r_PostTags_source_id" BIGINT NOT NULL, "r_PostTags_source_dtype" TEXT NOT NULL, "r_PostTags_target_id" BIGINT NOT NULL, PRIMARY KEY ("r_PostTags_source_id", "r_PostTags_target_id"), CHECK ("r_PostTags_source_dtype" IS NULL OR "r_PostTags_source_dtype" IN ('Post','SponsoredPost')));
ALTER TABLE "c_SponsoredPost" ADD CONSTRAINT "fk_c_SponsoredPost_0" FOREIGN KEY ("id", "dtype") REFERENCES "c_Post" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_AuthorPosts" ADD CONSTRAINT "fk_l_AuthorPosts_0" FOREIGN KEY ("r_AuthorPosts_source_id") REFERENCES "c_Author" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_AuthorPosts" ADD CONSTRAINT "fk_l_AuthorPosts_1" FOREIGN KEY ("r_AuthorPosts_target_id", "r_AuthorPosts_target_dtype") REFERENCES "c_Post" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PostComments" ADD CONSTRAINT "fk_l_PostComments_0" FOREIGN KEY ("r_PostComments_source_id", "r_PostComments_source_dtype") REFERENCES "c_Post" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PostComments" ADD CONSTRAINT "fk_l_PostComments_1" FOREIGN KEY ("r_PostComments_target_id") REFERENCES "c_Comment" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PostTags" ADD CONSTRAINT "fk_l_PostTags_0" FOREIGN KEY ("r_PostTags_source_id", "r_PostTags_source_dtype") REFERENCES "c_Post" ("id", "dtype") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE "l_PostTags" ADD CONSTRAINT "fk_l_PostTags_1" FOREIGN KEY ("r_PostTags_target_id") REFERENCES "c_Tag" ("id") MATCH FULL DEFERRABLE INITIALLY DEFERRED;
CREATE FUNCTION "require_AuthorPosts"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Post" t WHERE (t.dtype IN ('Post','SponsoredPost')) AND NOT EXISTS (SELECT 1 FROM "l_AuthorPosts" l WHERE l."r_AuthorPosts_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: AuthorPosts'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_AuthorPosts_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Post" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AuthorPosts"();
CREATE CONSTRAINT TRIGGER "ct_AuthorPosts_link" AFTER INSERT OR UPDATE OR DELETE ON "l_AuthorPosts" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_AuthorPosts"();
CREATE FUNCTION "require_PostComments"() RETURNS trigger LANGUAGE plpgsql SET search_path FROM CURRENT AS $ymap$ BEGIN IF EXISTS (SELECT 1 FROM "c_Comment" t WHERE (TRUE) AND NOT EXISTS (SELECT 1 FROM "l_PostComments" l WHERE l."r_PostComments_target_id"=t.id)) THEN RAISE EXCEPTION 'Required target participation violated: PostComments'; END IF; RETURN NULL; END; $ymap$;
CREATE CONSTRAINT TRIGGER "ct_PostComments_target" AFTER INSERT OR UPDATE OR DELETE ON "c_Comment" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PostComments"();
CREATE CONSTRAINT TRIGGER "ct_PostComments_link" AFTER INSERT OR UPDATE OR DELETE ON "l_PostComments" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "require_PostComments"();